@js:
var html = typeof result === "string" ? result : String(result);
try {
  if (result && result.outerHtml) html = result.outerHtml();
} catch (e) {}

var doc = org.jsoup.Jsoup.parse(html, baseUrl);

var bookElements = doc.select(".cp-catalog-grid article");
var bookList = [];

for (var i = 0; i < bookElements.size(); i++) {
  var item = bookElements.get(i);
  var href = item.select("h2 a").attr("href");

  bookList.push({
    name: String(item.select("h2").text())
      .replace(/^【小说】/, "")
      .trim(),
    author: "",
    bookUrl: __lib.appendQueryString(href, {
      view: "catalog",
    }),
    coverUrl: item.select("img").attr("src"),
   rulePubDate: item.select("p span").eq(0)@text
  });
}

bookList;
